import React, { useState } from 'react';
import './AdminHome.css';  // We'll add custom CSS here for layout

const AdminHome = () => {
  // State to manage search and filter
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('All');

  // Dummy data for student rows
  const students = [
    { id: 1, name: 'Abinaya', department: 'CSE' },
    { id: 2, name: 'Bavan', department: 'ECE' },
    { id: 3, name: 'xavier', department: 'ME' },
    { id: 4, name: 'Samuel', department: 'EIE' },
    { id: 5, name: 'Mathan', department: 'FT' },
    { id: 6, name: 'Karthika', department: 'FD' },
    { id: 7, name: 'Saranya', department: 'MECH' },
    { id: 8, name: 'Samuel', department: 'BT' },
    { id: 9, name: 'Ranjith', department: 'CSD' },
    { id: 10, name: 'Sam', department: 'EEE' },
    { id: 11, name: 'Samuel', department: 'BME' },
    // Add more student data here
  ];

  // Handle search
  const filteredStudents = students.filter(student => {
    return (
      student.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
      (filter === 'All' || student.department === filter)
    );
  });

  return (
    <div className="admin-container">
      <div className="admin-header">
        <input
          type="text"
          placeholder="Search Students"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-bar"
        />

        <select value={filter} onChange={(e) => setFilter(e.target.value)} className="filter-dropdown">
          <option value="All">All Departments</option>
          <option value="CSE">CSE</option>
          <option value="ECE">ECE</option>
          <option value="ME">ME</option>
          {/* Add more filter options if needed */}
        </select>
      </div>

      <div className="student-list">
        {filteredStudents.map((student) => (
          <button key={student.id} className="student-row">
            {student.name} - {student.department}
          </button>
        ))}
      </div>
    </div>
  );
};

export default AdminHome;
